&lt;div class=&#34;img-wrap&#34;&gt;&lt;div class=&#34;img-bg&#34; style=&#34;background:#1D0C04&#34;&gt;&lt;img class=&#34;img&#34; src=&#34;https://bu.dusays.com/2023/06/01/6478937d7de6f.webp&#34; alt=&#34;优化不同宽度浏览的观感&#34; style=&#34;width:400px;&#34;/&gt;&lt;/div&gt;&lt;span class=&#34;image-caption&#34;&gt;优化不同宽度浏览的观感&lt;/span&gt;&lt;/div&gt;&lt;/div&gt;&lt;div class=&#34;tab-item-content&#34; id=&#34;image-4&#34;&gt;&lt;ol&gt;
