&lt;h2 id=&#34;mermaid-图&#34;&gt;&lt;a href=&#34;#mermaid-图&#34; class=&#34;headerlink&#34; title=&#34;mermaid 图&#34;&gt;&lt;/a&gt;mermaid 图&lt;/h2&gt;&lt;div class=&#34;note blue anzhiyufont anzhiyu-icon-bullhorn simple&#34;&gt;&lt;p&gt;使用&lt;code&gt;mermaid标签&lt;/code&gt;可以绘制Flowchart（流程图）、Sequence diagram（时序图 ）、Class Diagram（类别图）、State Diagram（状态图）、Gantt（甘特图）和Pie Chart（圆形图），具体可以查看&lt;a href=&#34;https://mermaid.js.org/#/&#34;&gt;mermaid文档&lt;/a&gt;&lt;/p&gt;
&lt;/div&gt;


&lt;p&gt;修改 &lt;code&gt;主题配置文件&lt;/code&gt;&lt;/p&gt;
&lt;figure class=&#34;highlight yml&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# mermaid&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# see https://github.com/mermaid-js/mermaid&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attr&#34;&gt;mermaid:&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;enable:&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;true&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;comment&#34;&gt;# built-in themes: default/forest/dark/neutral&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;theme:&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;attr&#34;&gt;light:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;default&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;attr&#34;&gt;dark:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;dark&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;div class=&#34;tabs&#34; id=&#34;mermaid&#34;&gt;&lt;ul class=&#34;nav-tabs&#34;&gt;&lt;button type=&#34;button&#34; class=&#34;tab &#34; data-href=&#34;mermaid-1&#34;&gt;标签语法&lt;/button&gt;&lt;button type=&#34;button&#34; class=&#34;tab  active&#34; data-href=&#34;mermaid-2&#34;&gt;样式预览&lt;/button&gt;&lt;button type=&#34;button&#34; class=&#34;tab &#34; data-href=&#34;mermaid-3&#34;&gt;示例源码&lt;/button&gt;&lt;/ul&gt;&lt;div class=&#34;tab-contents&#34;&gt;&lt;div class=&#34;tab-item-content&#34; id=&#34;mermaid-1&#34;&gt;&lt;figure class=&#34;highlight markdown&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% mermaid %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;内容&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% endmermaid %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;&lt;/div&gt;&lt;div class=&#34;tab-item-content active&#34; id=&#34;mermaid-2&#34;&gt;&lt;p&gt;&lt;img src=&#34;https://bu.dusays.com/2023/06/01/647889d3a16f8.png&#34; alt=&#34;mermaid&#34;&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&#34;tab-item-content&#34; id=&#34;mermaid-3&#34;&gt;&lt;figure class=&#34;highlight plaintext&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% mermaid %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;pie&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    title Key elements in Product X&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &amp;quot;Calcium&amp;quot; : 42.96&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &amp;quot;Potassium&amp;quot; : 50.05&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &amp;quot;Magnesium&amp;quot; : 10.01&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &amp;quot;Iron&amp;quot; :  5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% endmermaid %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;&lt;/div&gt;&lt;/div&gt;&lt;div class=&#34;tab-to-top&#34;&gt;&lt;button type=&#34;button&#34; aria-label=&#34;scroll to top&#34;&gt;&lt;i class=&#34;anzhiyufont anzhiyu-icon-arrow-up&#34;&gt;&lt;/i&gt;&lt;/button&gt;&lt;/div&gt;&lt;/div&gt;

&lt;h2 id=&#34;复选列表-checkbox&#34;&gt;&lt;a href=&#34;#复选列表-checkbox&#34; class=&#34;headerlink&#34; title=&#34;复选列表 checkbox&#34;&gt;&lt;/a&gt;复选列表 checkbox&lt;/h2&gt;&lt;div class=&#34;tabs&#34; id=&#34;checkbox&#34;&gt;&lt;ul class=&#34;nav-tabs&#34;&gt;&lt;button type=&#34;button&#34; class=&#34;tab &#34; data-href=&#34;checkbox-1&#34;&gt;标签语法&lt;/button&gt;&lt;button type=&#34;button&#34; class=&#34;tab &#34; data-href=&#34;checkbox-2&#34;&gt;配置参数&lt;/button&gt;&lt;button type=&#34;button&#34; class=&#34;tab  active&#34; data-href=&#34;checkbox-3&#34;&gt;样式预览&lt;/button&gt;&lt;button type=&#34;button&#34; class=&#34;tab &#34; data-href=&#34;checkbox-4&#34;&gt;示例源码&lt;/button&gt;&lt;/ul&gt;&lt;div class=&#34;tab-contents&#34;&gt;&lt;div class=&#34;tab-item-content&#34; id=&#34;checkbox-1&#34;&gt;&lt;figure class=&#34;highlight markdown&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% checkbox 样式参数（可选）, 文本（支持简单md） %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;&lt;/div&gt;&lt;div class=&#34;tab-item-content&#34; id=&#34;checkbox-2&#34;&gt;&lt;ol&gt;
&lt;li&gt;样式: plus, minus, times&lt;/li&gt;
&lt;li&gt;颜色: &lt;span class=&#39;p red&#39;&gt;red&lt;/span&gt;,&lt;span class=&#39;p yellow&#39;&gt;yellow&lt;/span&gt;,&lt;span class=&#39;p green&#39;&gt;green&lt;/span&gt;,&lt;span class=&#39;p cyan&#39;&gt;cyan&lt;/span&gt;,&lt;span class=&#39;p blue&#39;&gt;blue&lt;/span&gt;,&lt;span class=&#39;p gray&#39;&gt;gray&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;选中状态: checked&lt;/li&gt;
&lt;/ol&gt;&lt;/div&gt;&lt;div class=&#34;tab-item-content active&#34; id=&#34;checkbox-3&#34;&gt;&lt;div class=&#39;checkbox&#39;&gt;&lt;input type=&#34;checkbox&#34; /&gt;
            &lt;p&gt;纯文本测试&lt;/p&gt;
            &lt;/div&gt;
   &lt;div class=&#39;checkbox checked&#39;&gt;&lt;input type=&#34;checkbox&#34; checked=&#34;checked&#34;/&gt;
            &lt;p&gt;支持简单的 &lt;a href=&#34;https://guides.github.com/features/mastering-markdown/&#34;&gt;markdown&lt;/a&gt; 语法&lt;/p&gt;
            &lt;/div&gt;
   &lt;div class=&#39;checkbox red&#39;&gt;&lt;input type=&#34;checkbox&#34; /&gt;
            &lt;p&gt;支持自定义颜色&lt;/p&gt;
            &lt;/div&gt;
   &lt;div class=&#39;checkbox green checked&#39;&gt;&lt;input type=&#34;checkbox&#34; checked=&#34;checked&#34;/&gt;
            &lt;p&gt;绿色 + 默认选中&lt;/p&gt;
            &lt;/div&gt;
   &lt;div class=&#39;checkbox yellow checked&#39;&gt;&lt;input type=&#34;checkbox&#34; checked=&#34;checked&#34;/&gt;
            &lt;p&gt;黄色 + 默认选中&lt;/p&gt;
            &lt;/div&gt;
   &lt;div class=&#39;checkbox cyan checked&#39;&gt;&lt;input type=&#34;checkbox&#34; checked=&#34;checked&#34;/&gt;
            &lt;p&gt;青色 + 默认选中&lt;/p&gt;
            &lt;/div&gt;
   &lt;div class=&#39;checkbox blue checked&#39;&gt;&lt;input type=&#34;checkbox&#34; checked=&#34;checked&#34;/&gt;
            &lt;p&gt;蓝色 + 默认选中&lt;/p&gt;
            &lt;/div&gt;
   &lt;div class=&#39;checkbox plus green checked&#39;&gt;&lt;input type=&#34;checkbox&#34; checked=&#34;checked&#34;/&gt;
            &lt;p&gt;增加&lt;/p&gt;
            &lt;/div&gt;
   &lt;div class=&#39;checkbox minus yellow checked&#39;&gt;&lt;input type=&#34;checkbox&#34; checked=&#34;checked&#34;/&gt;
            &lt;p&gt;减少&lt;/p&gt;
            &lt;/div&gt;
   &lt;div class=&#39;checkbox times red checked&#39;&gt;&lt;input type=&#34;checkbox&#34; checked=&#34;checked&#34;/&gt;
            &lt;p&gt;叉&lt;/p&gt;
            &lt;/div&gt;&lt;/div&gt;&lt;div class=&#34;tab-item-content&#34; id=&#34;checkbox-4&#34;&gt;&lt;figure class=&#34;highlight markdown&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% checkbox 纯文本测试 %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% checkbox checked, 支持简单的 [&lt;span class=&#34;string&#34;&gt;markdown&lt;/span&gt;](&lt;span class=&#34;link&#34;&gt;https://guides.github.com/features/mastering-markdown/&lt;/span&gt;) 语法 %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% checkbox red, 支持自定义颜色 %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% checkbox green checked, 绿色 + 默认选中 %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% checkbox yellow checked, 黄色 + 默认选中 %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% checkbox cyan checked, 青色 + 默认选中 %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% checkbox blue checked, 蓝色 + 默认选中 %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% checkbox plus green checked, 增加 %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% checkbox minus yellow checked, 减少 %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% checkbox times red checked, 叉 %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;&lt;/div&gt;&lt;/div&gt;&lt;div class=&#34;tab-to-top&#34;&gt;&lt;button type=&#34;button&#34; aria-label=&#34;scroll to top&#34;&gt;&lt;i class=&#34;anzhiyufont anzhiyu-icon-arrow-up&#34;&gt;&lt;/i&gt;&lt;/button&gt;&lt;/div&gt;&lt;/div&gt;

&lt;h2 id=&#34;dogeplayer-多吉云播放器&#34;&gt;&lt;a href=&#34;#dogeplayer-多吉云播放器&#34; class=&#34;headerlink&#34; title=&#34;dogeplayer 多吉云播放器&#34;&gt;&lt;/a&gt;dogeplayer 多吉云播放器&lt;/h2&gt;&lt;div class=&#34;note blue anzhiyufont anzhiyu-icon-bullhorn simple&#34;&gt;&lt;p&gt;快捷引入&lt;a href=&#34;https://console.dogecloud.com/vod/overview&#34;&gt;多吉云视频&lt;/a&gt;&lt;/p&gt;
&lt;/div&gt;

&lt;div class=&#34;tabs&#34; id=&#34;label&#34;&gt;&lt;ul class=&#34;nav-tabs&#34;&gt;&lt;button type=&#34;button&#34; class=&#34;tab &#34; data-href=&#34;label-1&#34;&gt;标签语法&lt;/button&gt;&lt;button type=&#34;button&#34; class=&#34;tab &#34; data-href=&#34;label-2&#34;&gt;参数配置&lt;/button&gt;&lt;button type=&#34;button&#34; class=&#34;tab  active&#34; data-href=&#34;label-3&#34;&gt;样式预览&lt;/button&gt;&lt;button type=&#34;button&#34; class=&#34;tab &#34; data-href=&#34;label-4&#34;&gt;示例源码&lt;/button&gt;&lt;/ul&gt;&lt;div class=&#34;tab-contents&#34;&gt;&lt;div class=&#34;tab-item-content&#34; id=&#34;label-1&#34;&gt;&lt;figure class=&#34;highlight markdown&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% dogeplayer 4945 ebb742fd1f0b5a7b %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;&lt;/div&gt;&lt;div class=&#34;tab-item-content&#34; id=&#34;label-2&#34;&gt;&lt;p&gt;获取&lt;code&gt;userId&lt;/code&gt;与&lt;code&gt;vcode&lt;/code&gt;&lt;/p&gt;
&lt;p&gt;&lt;img src=&#34;https://bu.dusays.com/2023/06/01/64788b5bad729.webp&#34;&gt;&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th align=&#34;left&#34;&gt;参数&lt;/th&gt;
&lt;th align=&#34;left&#34;&gt;含义&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td align=&#34;left&#34;&gt;userId&lt;/td&gt;
&lt;td align=&#34;left&#34;&gt;多吉云userId&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td align=&#34;left&#34;&gt;vcode&lt;/td&gt;
&lt;td align=&#34;left&#34;&gt;视频vcode&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;&lt;/div&gt;&lt;div class=&#34;tab-item-content active&#34; id=&#34;label-3&#34;&gt;&lt;p&gt;&lt;img src=&#34;https://bu.dusays.com/2023/06/01/64788c12883b8.webp&#34;&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&#34;tab-item-content&#34; id=&#34;label-4&#34;&gt;&lt;figure class=&#34;highlight plaintext&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% dogeplayer 4945 ebb742fd1f0b5a7b %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;&lt;/div&gt;&lt;/div&gt;&lt;div class=&#34;tab-to-top&#34;&gt;&lt;button type=&#34;button&#34; aria-label=&#34;scroll to top&#34;&gt;&lt;i class=&#34;anzhiyufont anzhiyu-icon-arrow-up&#34;&gt;&lt;/i&gt;&lt;/button&gt;&lt;/div&gt;&lt;/div&gt;

&lt;h2 id=&#34;折叠框-folding&#34;&gt;&lt;a href=&#34;#折叠框-folding&#34; class=&#34;headerlink&#34; title=&#34;折叠框 folding&#34;&gt;&lt;/a&gt;折叠框 folding&lt;/h2&gt;&lt;div class=&#34;note blue anzhiyufont anzhiyu-icon-bullhorn disabled&#34;&gt;&lt;p&gt;折叠框folding&lt;/p&gt;
&lt;/div&gt;

&lt;div class=&#34;tabs&#34; id=&#34;folding&#34;&gt;&lt;ul class=&#34;nav-tabs&#34;&gt;&lt;button type=&#34;button&#34; class=&#34;tab &#34; data-href=&#34;folding-1&#34;&gt;标签语法&lt;/button&gt;&lt;button type=&#34;button&#34; class=&#34;tab &#34; data-href=&#34;folding-2&#34;&gt;配置参数&lt;/button&gt;&lt;button type=&#34;button&#34; class=&#34;tab  active&#34; data-href=&#34;folding-3&#34;&gt;样式预览&lt;/button&gt;&lt;button type=&#34;button&#34; class=&#34;tab &#34; data-href=&#34;folding-4&#34;&gt;示例源码&lt;/button&gt;&lt;/ul&gt;&lt;div class=&#34;tab-contents&#34;&gt;&lt;div class=&#34;tab-item-content&#34; id=&#34;folding-1&#34;&gt;&lt;figure class=&#34;highlight markdown&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% folding 参数（可选）, 标题 %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;![](&lt;span class=&#34;link&#34;&gt;https://bu.dusays.com/2023/06/01/64788d71c832d.webp&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% endfolding %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;&lt;/div&gt;&lt;div class=&#34;tab-item-content&#34; id=&#34;folding-2&#34;&gt;&lt;ol&gt;
&lt;li&gt;颜色：blue, cyan, green, yellow, red&lt;/li&gt;
&lt;li&gt;状态：状态填写 open 代表默认打开。&lt;/li&gt;
&lt;/ol&gt;&lt;/div&gt;&lt;div class=&#34;tab-item-content active&#34; id=&#34;folding-3&#34;&gt;&lt;details class=&#34;folding-tag&#34; &gt;&lt;summary&gt; 查看图片测试 &lt;/summary&gt;
              &lt;div class=&#39;content&#39;&gt;
              &lt;p&gt;&lt;img src=&#34;https://bu.dusays.com/2023/06/01/64788d71c832d.webp&#34;&gt;&lt;/p&gt;
              &lt;/div&gt;
            &lt;/details&gt;

&lt;details class=&#34;folding-tag&#34; cyan open&gt;&lt;summary&gt; 查看默认打开的折叠框 &lt;/summary&gt;
              &lt;div class=&#39;content&#39;&gt;
              &lt;p&gt;这是一个默认打开的折叠框。&lt;/p&gt;
              &lt;/div&gt;
            &lt;/details&gt;

&lt;details class=&#34;folding-tag&#34; green&gt;&lt;summary&gt; 查看代码测试 &lt;/summary&gt;
              &lt;div class=&#39;content&#39;&gt;
              &lt;figure class=&#34;highlight markdown&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;![](&lt;span class=&#34;link&#34;&gt;https://bu.dusays.com/2023/06/01/64788d71c832d.webp&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
              &lt;/div&gt;
            &lt;/details&gt;

&lt;details class=&#34;folding-tag&#34; yellow&gt;&lt;summary&gt; 查看列表测试 &lt;/summary&gt;
              &lt;div class=&#39;content&#39;&gt;
              &lt;ul&gt;&lt;li&gt;haha&lt;/li&gt;&lt;li&gt;hehe&lt;/li&gt;&lt;/ul&gt;
              &lt;/div&gt;
            &lt;/details&gt;

&lt;details class=&#34;folding-tag&#34; red&gt;&lt;summary&gt; 查看嵌套测试 &lt;/summary&gt;
              &lt;div class=&#39;content&#39;&gt;
              &lt;details class=&#34;folding-tag&#34; blue&gt;&lt;summary&gt; 查看嵌套测试2 &lt;/summary&gt;              &lt;div class=&#39;content&#39;&gt;              &lt;details class=&#34;folding-tag&#34; &gt;&lt;summary&gt; 查看嵌套测试3 &lt;/summary&gt;              &lt;div class=&#39;content&#39;&gt;              &lt;p&gt;hahaha &lt;span&gt;&lt;img src=&#39;https://bu.dusays.com/2023/06/01/64788cd5a356b.png&#39; style=&#39;height:24px&#39;&gt;&lt;/span&gt;&lt;/p&gt;              &lt;/div&gt;            &lt;/details&gt;              &lt;/div&gt;            &lt;/details&gt;
              &lt;/div&gt;
            &lt;/details&gt;&lt;/div&gt;&lt;div class=&#34;tab-item-content&#34; id=&#34;folding-4&#34;&gt;&lt;figure class=&#34;highlight markdown&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;11&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;12&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;13&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;14&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;15&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;16&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;17&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;18&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;19&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;20&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;21&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;22&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;23&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;24&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;25&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;26&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;27&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;28&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;29&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;30&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;31&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;32&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;33&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;34&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;35&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;36&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% folding 查看图片测试 %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;![](&lt;span class=&#34;link&#34;&gt;https://bu.dusays.com/2023/06/01/64788d71c832d.webp&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% endfolding %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% folding cyan open, 查看默认打开的折叠框 %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;这是一个默认打开的折叠框。&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% endfolding %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% folding green, 查看代码测试 %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;假装这里有代码块（代码块没法嵌套代码块）&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% endfolding %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% folding yellow, 查看列表测试 %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;bullet&#34;&gt;-&lt;/span&gt; haha&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;bullet&#34;&gt;-&lt;/span&gt; hehe&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% endfolding %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% folding red, 查看嵌套测试 %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% folding blue, 查看嵌套测试2 %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% folding 查看嵌套测试3 %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;hahaha &lt;span class=&#34;language-xml&#34;&gt;&lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;span&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;language-xml&#34;&gt;&lt;span class=&#34;tag&#34;&gt;&amp;lt;&lt;span class=&#34;name&#34;&gt;img&lt;/span&gt; &lt;span class=&#34;attr&#34;&gt;src&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;#x27;https://bu.dusays.com/2023/06/01/64788cd5a356b.png&amp;#x27;&lt;/span&gt; &lt;span class=&#34;attr&#34;&gt;style&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;#x27;height:24px&amp;#x27;&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;language-xml&#34;&gt;&lt;span class=&#34;tag&#34;&gt;&amp;lt;/&lt;span class=&#34;name&#34;&gt;span&lt;/span&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% endfolding %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% endfolding %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% endfolding %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;&lt;/div&gt;&lt;/div&gt;&lt;div class=&#34;tab-to-top&#34;&gt;&lt;button type=&#34;button&#34; aria-label=&#34;scroll to top&#34;&gt;&lt;i class=&#34;anzhiyufont anzhiyu-icon-arrow-up&#34;&gt;&lt;/i&gt;&lt;/button&gt;&lt;/div&gt;&lt;/div&gt;

&lt;h2 id=&#34;Gallery-相册图库&#34;&gt;&lt;a href=&#34;#Gallery-相册图库&#34; class=&#34;headerlink&#34; title=&#34;Gallery 相册图库&#34;&gt;&lt;/a&gt;Gallery 相册图库&lt;/h2&gt;&lt;p&gt;一个图库集合。&lt;/p&gt;
&lt;div class=&#34;tabs&#34; id=&#34;gallery&#34;&gt;&lt;ul class=&#34;nav-tabs no-default&#34;&gt;&lt;/ul&gt;&lt;div class=&#34;tab-contents&#34;&gt;&lt;/div&gt;&lt;div class=&#34;tab-to-top&#34;&gt;&lt;button type=&#34;button&#34; aria-label=&#34;scroll to top&#34;&gt;&lt;i class=&#34;anzhiyufont anzhiyu-icon-arrow-up&#34;&gt;&lt;/i&gt;&lt;/button&gt;&lt;/div&gt;&lt;/div&gt;

&lt;h2 id=&#34;tag-hide&#34;&gt;&lt;a href=&#34;#tag-hide&#34; class=&#34;headerlink&#34; title=&#34;tag-hide&#34;&gt;&lt;/a&gt;tag-hide&lt;/h2&gt;&lt;div class=&#34;note blue anzhiyufont anzhiyu-icon-bullhorn flat&#34;&gt;&lt;p&gt;如果你想把一些文字、内容隐藏起来，并提供按钮让用户点击显示。可以使用这个标签外挂。&lt;br&gt;请注意，tag-hide内的标签外挂content内都不建议有h1 - h6 等标题。因为Toc会把隐藏内容标题也显示出来，而且当滚动屏幕时，如果隐藏内容没有显示出来，会导致Toc的滚动出现异常。&lt;/p&gt;
&lt;/div&gt;

&lt;div class=&#34;tabs&#34; id=&#34;tag-hide&#34;&gt;&lt;ul class=&#34;nav-tabs&#34;&gt;&lt;button type=&#34;button&#34; class=&#34;tab  active&#34; data-href=&#34;tag-hide-1&#34;&gt;inline&lt;/button&gt;&lt;button type=&#34;button&#34; class=&#34;tab &#34; data-href=&#34;tag-hide-2&#34;&gt;Block&lt;/button&gt;&lt;button type=&#34;button&#34; class=&#34;tab &#34; data-href=&#34;tag-hide-3&#34;&gt;Toggle&lt;/button&gt;&lt;/ul&gt;&lt;div class=&#34;tab-contents&#34;&gt;&lt;div class=&#34;tab-item-content active&#34; id=&#34;tag-hide-1&#34;&gt;&lt;p&gt;&lt;code&gt;inline&lt;/code&gt; 在文本里面添加按钮隐藏内容，只限文字&lt;/p&gt;
&lt;p&gt;( content不能包含英文逗号，可用&lt;code&gt;&amp;amp;sbquo;&lt;/code&gt;)&lt;/p&gt;
&lt;figure class=&#34;highlight markdown&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% hideInline content,display,bg,color %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;ul&gt;
&lt;li&gt;&lt;p&gt;content: 文本内容&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;display: 按钮显示的文字(可选)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;bg: 按钮的背景颜色(可选)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;color: 按钮文字的颜色(可选)&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;blockquote&gt;
&lt;p&gt;Demo&lt;/p&gt;
&lt;/blockquote&gt;
&lt;figure class=&#34;highlight markdown&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;哪个英文字母最酷？ &amp;#123;% hideInline 因为西装裤(C装酷),查看答案,#FF7242,#fff %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;门里站着一个人? &amp;#123;% hideInline 闪 %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;哪个英文字母最酷？ &lt;span class=&#34;hide-inline&#34;&gt;&lt;button type=&#34;button&#34; class=&#34;hide-button&#34; style=&#34;background-color: #FF7242;color: #fff&#34;&gt;查看答案&lt;br&gt;  &lt;/button&gt;&lt;span class=&#34;hide-content&#34;&gt;因为西装裤(C装酷)&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;门里站着一个人? &lt;span class=&#34;hide-inline&#34;&gt;&lt;button type=&#34;button&#34; class=&#34;hide-button&#34; style=&#34;&#34;&gt;Click&lt;br&gt;  &lt;/button&gt;&lt;span class=&#34;hide-content&#34;&gt;闪&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&#34;tab-item-content&#34; id=&#34;tag-hide-2&#34;&gt;&lt;p&gt;&lt;code&gt;block&lt;/code&gt;独立的block隐藏内容，可以隐藏很多内容，包括图片，代码块等等&lt;/p&gt;
&lt;p&gt;( display 不能包含英文逗号，可用&lt;code&gt;&amp;amp;sbquo;&lt;/code&gt;)&lt;/p&gt;
&lt;figure class=&#34;highlight markdown&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% hideBlock display,bg,color %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;content&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% endhideBlock %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;ul&gt;
&lt;li&gt;&lt;p&gt;content: 文本内容&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;display: 按钮显示的文字(可选)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;bg: 按钮的背景颜色(可选)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;color: 按钮文字的颜色(可选)&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;blockquote&gt;
&lt;p&gt;Demo&lt;/p&gt;
&lt;/blockquote&gt;
&lt;figure class=&#34;highlight markdown&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;查看答案&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% hideBlock 查看答案 %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;傻子，怎么可能有答案&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% endhideBlock %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;查看答案&lt;/p&gt;
&lt;div class=&#34;hide-block&#34;&gt;&lt;button type=&#34;button&#34; class=&#34;hide-button&#34; style=&#34;&#34;&gt;查看答案
    &lt;/button&gt;&lt;div class=&#34;hide-content&#34;&gt;&lt;p&gt;傻子，怎么可能有答案&lt;/p&gt;
&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;&lt;div class=&#34;tab-item-content&#34; id=&#34;tag-hide-3&#34;&gt;&lt;p&gt;如果你需要展示的内容太多，可以把它隐藏在收缩框里，需要时再把它展开。&lt;/p&gt;
&lt;p&gt;( display 不能包含英文逗号，可用&lt;code&gt;&amp;amp;sbquo;&lt;/code&gt;)&lt;/p&gt;
&lt;figure class=&#34;highlight markdown&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% hideToggle display,bg,color %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;content&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% endhideToggle %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;blockquote&gt;
&lt;p&gt;Demo&lt;/p&gt;
&lt;/blockquote&gt;
&lt;details class=&#34;toggle&#34; &gt;&lt;summary class=&#34;toggle-button&#34; style=&#34;&#34;&gt;AnZhiYu主题安装方法&lt;/summary&gt;&lt;div class=&#34;toggle-content&#34;&gt;&lt;p&gt;在你的博客根目录里&lt;/p&gt;
&lt;p&gt;git clone -b master &lt;a href=&#34;https://github.com/anzhiyu-c/hexo-theme-anzhiyu.git&#34;&gt;https://github.com/anzhiyu-c/hexo-theme-anzhiyu.git&lt;/a&gt; themes&amp;#x2F;anzhiyu&lt;/p&gt;
&lt;p&gt;如果想要安装比较新的dev分支，可以&lt;/p&gt;
&lt;p&gt;git clone -b dev &lt;a href=&#34;https://github.com/anzhiyu-c/hexo-theme-anzhiyu.git&#34;&gt;https://github.com/anzhiyu-c/hexo-theme-anzhiyu.git&lt;/a&gt; themes&amp;#x2F;anzhiyu&lt;/p&gt;
&lt;/div&gt;&lt;/details&gt;&lt;/div&gt;&lt;/div&gt;&lt;div class=&#34;tab-to-top&#34;&gt;&lt;button type=&#34;button&#34; aria-label=&#34;scroll to top&#34;&gt;&lt;i class=&#34;anzhiyufont anzhiyu-icon-arrow-up&#34;&gt;&lt;/i&gt;&lt;/button&gt;&lt;/div&gt;&lt;/div&gt;


&lt;h2 id=&#34;链接卡片-link&#34;&gt;&lt;a href=&#34;#链接卡片-link&#34; class=&#34;headerlink&#34; title=&#34;链接卡片 link&#34;&gt;&lt;/a&gt;链接卡片 link&lt;/h2&gt;&lt;div class=&#34;tabs&#34; id=&#34;link&#34;&gt;&lt;ul class=&#34;nav-tabs&#34;&gt;&lt;button type=&#34;button&#34; class=&#34;tab &#34; data-href=&#34;link-1&#34;&gt;标签语法&lt;/button&gt;&lt;button type=&#34;button&#34; class=&#34;tab  active&#34; data-href=&#34;link-2&#34;&gt;样式预览&lt;/button&gt;&lt;button type=&#34;button&#34; class=&#34;tab &#34; data-href=&#34;link-3&#34;&gt;示例源码&lt;/button&gt;&lt;/ul&gt;&lt;div class=&#34;tab-contents&#34;&gt;&lt;div class=&#34;tab-item-content&#34; id=&#34;link-1&#34;&gt;&lt;figure class=&#34;highlight markdown&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% link 标题, 站点描述, 链接, 图片链接（可选） %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;&lt;/div&gt;&lt;div class=&#34;tab-item-content active&#34; id=&#34;link-2&#34;&gt;&lt;div calss=&#39;anzhiyu-tag-link&#39;&gt;&lt;a class=&#34;tag-Link&#34; target=&#34;_blank&#34; href=&#34;https://github.com/owen0o0/getFavicon&#34;&gt;
    &lt;div class=&#34;tag-link-tips&#34;&gt;引用站外地址&lt;/div&gt;
    &lt;div class=&#34;tag-link-bottom&#34;&gt;
        &lt;div class=&#34;tag-link-left&#34; style=&#34;&#34;&gt;
          &lt;i class=&#34;anzhiyufont anzhiyu-icon-link&#34; style=&#34;&#34;&gt;&lt;/i&gt;
        &lt;/div&gt;
        &lt;div class=&#34;tag-link-right&#34;&gt;
            &lt;div class=&#34;tag-link-title&#34;&gt;获取网站的Favicon图标并显示在你的网页上&lt;/div&gt;
            &lt;div class=&#34;tag-link-sitename&#34;&gt;owen0o0&lt;/div&gt;
        &lt;/div&gt;
        &lt;i class=&#34;anzhiyufont anzhiyu-icon-angle-right&#34;&gt;&lt;/i&gt;
    &lt;/div&gt;
    &lt;/a&gt;&lt;/div&gt;&lt;/div&gt;&lt;div class=&#34;tab-item-content&#34; id=&#34;link-3&#34;&gt;&lt;figure class=&#34;highlight markdown&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% link 获取网站的Favicon图标并显示在你的网页上,owen0o0,https://github.com/owen0o0/getFavicon %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;&lt;/div&gt;&lt;/div&gt;&lt;div class=&#34;tab-to-top&#34;&gt;&lt;button type=&#34;button&#34; aria-label=&#34;scroll to top&#34;&gt;&lt;i class=&#34;anzhiyufont anzhiyu-icon-arrow-up&#34;&gt;&lt;/i&gt;&lt;/button&gt;&lt;/div&gt;&lt;/div&gt;

&lt;h2 id=&#34;单选列表-radio&#34;&gt;&lt;a href=&#34;#单选列表-radio&#34; class=&#34;headerlink&#34; title=&#34;单选列表 radio&#34;&gt;&lt;/a&gt;单选列表 radio&lt;/h2&gt;&lt;div class=&#34;tabs&#34; id=&#34;radio&#34;&gt;&lt;ul class=&#34;nav-tabs&#34;&gt;&lt;button type=&#34;button&#34; class=&#34;tab &#34; data-href=&#34;radio-1&#34;&gt;标签语法&lt;/button&gt;&lt;button type=&#34;button&#34; class=&#34;tab &#34; data-href=&#34;radio-2&#34;&gt;配置参数&lt;/button&gt;&lt;button type=&#34;button&#34; class=&#34;tab  active&#34; data-href=&#34;radio-3&#34;&gt;样式预览&lt;/button&gt;&lt;button type=&#34;button&#34; class=&#34;tab &#34; data-href=&#34;radio-4&#34;&gt;示例源码&lt;/button&gt;&lt;/ul&gt;&lt;div class=&#34;tab-contents&#34;&gt;&lt;div class=&#34;tab-item-content&#34; id=&#34;radio-1&#34;&gt;&lt;figure class=&#34;highlight markdown&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% radio 样式参数（可选）, 文本（支持简单md） %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;&lt;/div&gt;&lt;div class=&#34;tab-item-content&#34; id=&#34;radio-2&#34;&gt;&lt;ol&gt;
&lt;li&gt;颜色: &lt;span class=&#39;p red&#39;&gt;red&lt;/span&gt;,&lt;span class=&#39;p yellow&#39;&gt;yellow&lt;/span&gt;,&lt;span class=&#39;p green&#39;&gt;green&lt;/span&gt;,&lt;span class=&#39;p cyan&#39;&gt;cyan&lt;/span&gt;,&lt;span class=&#39;p blue&#39;&gt;blue&lt;/span&gt;,&lt;span class=&#39;p gray&#39;&gt;gray&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;选中状态: checked&lt;/li&gt;
&lt;/ol&gt;&lt;/div&gt;&lt;div class=&#34;tab-item-content active&#34; id=&#34;radio-3&#34;&gt;&lt;div class=&#39;checkbox&#39;&gt;&lt;input type=&#34;radio&#34; /&gt;
            &lt;p&gt;纯文本测试&lt;/p&gt;
            &lt;/div&gt;
   &lt;div class=&#39;checkbox checked&#39;&gt;&lt;input type=&#34;radio&#34; checked=&#34;checked&#34;/&gt;
            &lt;p&gt;支持简单的 &lt;a href=&#34;https://guides.github.com/features/mastering-markdown/&#34;&gt;markdown&lt;/a&gt; 语法&lt;/p&gt;
            &lt;/div&gt;
   &lt;div class=&#39;checkbox red&#39;&gt;&lt;input type=&#34;radio&#34; /&gt;
            &lt;p&gt;支持自定义颜色&lt;/p&gt;
            &lt;/div&gt;
   &lt;div class=&#39;checkbox green&#39;&gt;&lt;input type=&#34;radio&#34; /&gt;
            &lt;p&gt;绿色&lt;/p&gt;
            &lt;/div&gt;
   &lt;div class=&#39;checkbox yellow&#39;&gt;&lt;input type=&#34;radio&#34; /&gt;
            &lt;p&gt;黄色&lt;/p&gt;
            &lt;/div&gt;
   &lt;div class=&#39;checkbox cyan&#39;&gt;&lt;input type=&#34;radio&#34; /&gt;
            &lt;p&gt;青色&lt;/p&gt;
            &lt;/div&gt;
   &lt;div class=&#39;checkbox blue&#39;&gt;&lt;input type=&#34;radio&#34; /&gt;
            &lt;p&gt;蓝色&lt;/p&gt;
            &lt;/div&gt;&lt;/div&gt;&lt;div class=&#34;tab-item-content&#34; id=&#34;radio-4&#34;&gt;&lt;figure class=&#34;highlight markdown&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% radio 纯文本测试 %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% radio checked, 支持简单的 [&lt;span class=&#34;string&#34;&gt;markdown&lt;/span&gt;](&lt;span class=&#34;link&#34;&gt;https://guides.github.com/features/mastering-markdown/&lt;/span&gt;) 语法 %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% radio red, 支持自定义颜色 %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% radio green, 绿色 %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% radio yellow, 黄色 %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% radio cyan, 青色 %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% radio blue, 蓝色 %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;&lt;/div&gt;&lt;/div&gt;&lt;div class=&#34;tab-to-top&#34;&gt;&lt;button type=&#34;button&#34; aria-label=&#34;scroll to top&#34;&gt;&lt;i class=&#34;anzhiyufont anzhiyu-icon-arrow-up&#34;&gt;&lt;/i&gt;&lt;/button&gt;&lt;/div&gt;&lt;/div&gt;

&lt;h2 id=&#34;上标标签-tip&#34;&gt;&lt;a href=&#34;#上标标签-tip&#34; class=&#34;headerlink&#34; title=&#34;上标标签 tip&#34;&gt;&lt;/a&gt;上标标签 tip&lt;/h2&gt;&lt;div class=&#34;tip cogs&#34;&gt;&lt;p&gt;主要样式参考自&lt;a href=&#34;https://www.antmoe.com/posts/3b43914f/&#34;&gt;小康的 butterfly 渐变背景标签&lt;/a&gt;&lt;/p&gt;
&lt;/div&gt;

&lt;div class=&#34;tabs&#34; id=&#34;tip&#34;&gt;&lt;ul class=&#34;nav-tabs&#34;&gt;&lt;button type=&#34;button&#34; class=&#34;tab &#34; data-href=&#34;tip-1&#34;&gt;标签语法&lt;/button&gt;&lt;button type=&#34;button&#34; class=&#34;tab &#34; data-href=&#34;tip-2&#34;&gt;配置参数&lt;/button&gt;&lt;button type=&#34;button&#34; class=&#34;tab  active&#34; data-href=&#34;tip-3&#34;&gt;样式预览&lt;/button&gt;&lt;button type=&#34;button&#34; class=&#34;tab &#34; data-href=&#34;tip-4&#34;&gt;示例源码&lt;/button&gt;&lt;/ul&gt;&lt;div class=&#34;tab-contents&#34;&gt;&lt;div class=&#34;tab-item-content&#34; id=&#34;tip-1&#34;&gt;&lt;figure class=&#34;highlight markdown&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% tip [参数，可选] %&amp;#125;文本内容&amp;#123;% endtip %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;&lt;/div&gt;&lt;div class=&#34;tab-item-content&#34; id=&#34;tip-2&#34;&gt;&lt;ol&gt;
&lt;li&gt;样式: success,error,warning,bolt,ban,home,sync,cogs,key,bell&lt;/li&gt;
&lt;li&gt;自定义图标: 支持 fontawesome。&lt;/li&gt;
&lt;/ol&gt;&lt;/div&gt;&lt;div class=&#34;tab-item-content active&#34; id=&#34;tip-3&#34;&gt;&lt;div class=&#34;tip &#34;&gt;&lt;p&gt;default&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&#34;tip info&#34;&gt;&lt;p&gt;info&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&#34;tip success&#34;&gt;&lt;p&gt;success&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&#34;tip error&#34;&gt;&lt;p&gt;error&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&#34;tip warning&#34;&gt;&lt;p&gt;warning&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&#34;tip bolt&#34;&gt;&lt;p&gt;bolt&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&#34;tip ban&#34;&gt;&lt;p&gt;ban&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&#34;tip home&#34;&gt;&lt;p&gt;home&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&#34;tip sync&#34;&gt;&lt;p&gt;sync&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&#34;tip cogs&#34;&gt;&lt;p&gt;cogs&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&#34;tip key&#34;&gt;&lt;p&gt;key&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&#34;tip bell&#34;&gt;&lt;p&gt;bell&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&#34;tip fa-atom&#34;&gt;&lt;p&gt;自定义 font awesome 图标&lt;/p&gt;
&lt;/div&gt;&lt;/div&gt;&lt;div class=&#34;tab-item-content&#34; id=&#34;tip-4&#34;&gt;&lt;figure class=&#34;highlight markdown&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;11&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;12&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;13&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% tip %&amp;#125;default&amp;#123;% endtip %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% tip info %&amp;#125;info&amp;#123;% endtip %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% tip success %&amp;#125;success&amp;#123;% endtip %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% tip error %&amp;#125;error&amp;#123;% endtip %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% tip warning %&amp;#125;warning&amp;#123;% endtip %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% tip bolt %&amp;#125;bolt&amp;#123;% endtip %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% tip ban %&amp;#125;ban&amp;#123;% endtip %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% tip home %&amp;#125;home&amp;#123;% endtip %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% tip sync %&amp;#125;sync&amp;#123;% endtip %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% tip cogs %&amp;#125;cogs&amp;#123;% endtip %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% tip key %&amp;#125;key&amp;#123;% endtip %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% tip bell %&amp;#125;bell&amp;#123;% endtip %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% tip fa-atom %&amp;#125;自定义 font awesome 图标&amp;#123;% endtip %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;&lt;/div&gt;&lt;/div&gt;&lt;div class=&#34;tab-to-top&#34;&gt;&lt;button type=&#34;button&#34; aria-label=&#34;scroll to top&#34;&gt;&lt;i class=&#34;anzhiyufont anzhiyu-icon-arrow-up&#34;&gt;&lt;/i&gt;&lt;/button&gt;&lt;/div&gt;&lt;/div&gt;

&lt;h2 id=&#34;Note-Bootstrap-Callout&#34;&gt;&lt;a href=&#34;#Note-Bootstrap-Callout&#34; class=&#34;headerlink&#34; title=&#34;Note (Bootstrap Callout)&#34;&gt;&lt;/a&gt;Note (Bootstrap Callout)&lt;/h2&gt;&lt;div class=&#34;tabs&#34; id=&#34;note&#34;&gt;&lt;ul class=&#34;nav-tabs&#34;&gt;&lt;button type=&#34;button&#34; class=&#34;tab &#34; data-href=&#34;note-1&#34;&gt;通用配置&lt;/button&gt;&lt;button type=&#34;button&#34; class=&#34;tab &#34; data-href=&#34;note-2&#34;&gt;语法格式&lt;/button&gt;&lt;button type=&#34;button&#34; class=&#34;tab &#34; data-href=&#34;note-3&#34;&gt;配置参数&lt;/button&gt;&lt;button type=&#34;button&#34; class=&#34;tab  active&#34; data-href=&#34;note-4&#34;&gt;样式预览&lt;/button&gt;&lt;button type=&#34;button&#34; class=&#34;tab &#34; data-href=&#34;note-5&#34;&gt;示例源码&lt;/button&gt;&lt;/ul&gt;&lt;div class=&#34;tab-contents&#34;&gt;&lt;div class=&#34;tab-item-content&#34; id=&#34;note-1&#34;&gt;&lt;p&gt;修改主题配置文件&lt;/p&gt;
&lt;figure class=&#34;highlight yml&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;11&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;12&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attr&#34;&gt;note:&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;comment&#34;&gt;# Note tag style values:&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;comment&#34;&gt;#  - simple    bs-callout old alert style. Default.&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;comment&#34;&gt;#  - modern    bs-callout new (v2-v3) alert style.&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;comment&#34;&gt;#  - flat      flat callout style with background, like on Mozilla or StackOverflow.&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;comment&#34;&gt;#  - disabled  disable all CSS styles import of note tag.&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;style:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;simple&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;icons:&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;false&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;border_radius:&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;comment&#34;&gt;# Offset lighter of background in % for modern and flat styles (modern: -12 | 12; flat: -18 | 6).&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;comment&#34;&gt;# Offset also applied to label tag variables. This option can work with disabled note tag.&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;attr&#34;&gt;light_bg_offset:&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;&lt;code&gt;Note&lt;/code&gt;标签外挂有两种用法。&lt;code&gt;icons&lt;/code&gt;和&lt;code&gt;light_bg_offset&lt;/code&gt;只对方法一生效。&lt;/p&gt;
&lt;p&gt;&lt;code&gt;fontawesome&lt;/code&gt;图标需开启主题配置文件中&lt;code&gt;icons.fontawesome&lt;/code&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&#34;tab-item-content&#34; id=&#34;note-2&#34;&gt;&lt;p&gt;&lt;code&gt;方法一&lt;/code&gt;&lt;/p&gt;
&lt;figure class=&#34;highlight markdown&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% note [class] [no-icon] [style] %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;Any content (support inline tags too.io).&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% endnote %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;&lt;code&gt;方法二&lt;/code&gt;&lt;/p&gt;
&lt;figure class=&#34;highlight markdown&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% note [color] [icon] [style] %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;Any content (support inline tags too.io).&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% endnote %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;&lt;/div&gt;&lt;div class=&#34;tab-item-content&#34; id=&#34;note-3&#34;&gt;&lt;p&gt;&lt;code&gt;方法一&lt;/code&gt;&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th align=&#34;left&#34;&gt;参数&lt;/th&gt;
&lt;th align=&#34;left&#34;&gt;用法&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td align=&#34;left&#34;&gt;class&lt;/td&gt;
&lt;td align=&#34;left&#34;&gt;【可选】标识，不同的标识有不同的配色&lt;br&gt;（ default &amp;#x2F; primary &amp;#x2F; success &amp;#x2F; info &amp;#x2F; warning &amp;#x2F; danger ）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td align=&#34;left&#34;&gt;no-icon&lt;/td&gt;
&lt;td align=&#34;left&#34;&gt;【可选】不显示 icon&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td align=&#34;left&#34;&gt;style&lt;/td&gt;
&lt;td align=&#34;left&#34;&gt;【可选】可以覆盖配置中的 style&lt;br&gt;（simple&amp;#x2F;modern&amp;#x2F;flat&amp;#x2F;disabled）&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;p&gt;&lt;code&gt;方法二&lt;/code&gt;&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th align=&#34;left&#34;&gt;参数&lt;/th&gt;
&lt;th align=&#34;left&#34;&gt;用法&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td align=&#34;left&#34;&gt;class&lt;/td&gt;
&lt;td align=&#34;left&#34;&gt;【可选】标识，不同的标识有不同的配色&lt;br&gt;（ default &amp;#x2F; blue &amp;#x2F; pink &amp;#x2F; red &amp;#x2F; purple &amp;#x2F; orange &amp;#x2F; green ）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td align=&#34;left&#34;&gt;no-icon&lt;/td&gt;
&lt;td align=&#34;left&#34;&gt;【可选】可配置自定义 icon (支持 fontawesome 图标和主题内置的阿里图标,&lt;code&gt;fontawesome&lt;/code&gt;图标需开启主题配置文件中&lt;code&gt;icons.fontawesome&lt;/code&gt;, 也可以配置 no-icon )&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td align=&#34;left&#34;&gt;style&lt;/td&gt;
&lt;td align=&#34;left&#34;&gt;【可选】可以覆盖配置中的 style&lt;br&gt;（simple&amp;#x2F;modern&amp;#x2F;flat&amp;#x2F;disabled）&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;&lt;/div&gt;&lt;div class=&#34;tab-item-content active&#34; id=&#34;note-4&#34;&gt;&lt;p&gt;&lt;code&gt;方法一&lt;/code&gt;&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;&lt;code&gt;simple&lt;/code&gt;样式&lt;/li&gt;
&lt;/ol&gt;
&lt;div class=&#34;note simple&#34;&gt;&lt;p&gt;默认 提示块标签&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&#34;note default simple&#34;&gt;&lt;p&gt;default 提示块标签&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&#34;note primary simple&#34;&gt;&lt;p&gt;primary 提示块标签&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&#34;note success simple&#34;&gt;&lt;p&gt;success 提示块标签&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&#34;note info simple&#34;&gt;&lt;p&gt;info 提示块标签&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&#34;note warning simple&#34;&gt;&lt;p&gt;warning 提示块标签&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&#34;note danger simple&#34;&gt;&lt;p&gt;danger 提示块标签&lt;/p&gt;
&lt;/div&gt;


&lt;ol start=&#34;2&#34;&gt;
&lt;li&gt;&lt;code&gt;modern&lt;/code&gt;样式&lt;/li&gt;
&lt;/ol&gt;
&lt;div class=&#34;note modern&#34;&gt;&lt;p&gt;默认 提示块标签&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&#34;note default modern&#34;&gt;&lt;p&gt;default 提示块标签&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&#34;note primary modern&#34;&gt;&lt;p&gt;primary 提示块标签&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&#34;note success modern&#34;&gt;&lt;p&gt;success 提示块标签&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&#34;note info modern&#34;&gt;&lt;p&gt;info 提示块标签&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&#34;note warning modern&#34;&gt;&lt;p&gt;warning 提示块标签&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&#34;note danger modern&#34;&gt;&lt;p&gt;danger 提示块标签&lt;/p&gt;
&lt;/div&gt;


&lt;ol start=&#34;3&#34;&gt;
&lt;li&gt;&lt;code&gt;flat&lt;/code&gt;样式&lt;/li&gt;
&lt;/ol&gt;
&lt;div class=&#34;note flat&#34;&gt;&lt;p&gt;默认 提示块标签&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&#34;note default flat&#34;&gt;&lt;p&gt;default 提示块标签&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&#34;note primary flat&#34;&gt;&lt;p&gt;primary 提示块标签&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&#34;note success flat&#34;&gt;&lt;p&gt;success 提示块标签&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&#34;note info flat&#34;&gt;&lt;p&gt;info 提示块标签&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&#34;note warning flat&#34;&gt;&lt;p&gt;warning 提示块标签&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&#34;note danger flat&#34;&gt;&lt;p&gt;danger 提示块标签&lt;/p&gt;
&lt;/div&gt;

&lt;ol start=&#34;4&#34;&gt;
&lt;li&gt;&lt;code&gt;disabled&lt;/code&gt;样式&lt;/li&gt;
&lt;/ol&gt;
&lt;div class=&#34;note disabled&#34;&gt;&lt;p&gt;默认 提示块标签&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&#34;note default disabled&#34;&gt;&lt;p&gt;default 提示块标签&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&#34;note primary disabled&#34;&gt;&lt;p&gt;primary 提示块标签&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&#34;note success disabled&#34;&gt;&lt;p&gt;success 提示块标签&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&#34;note info disabled&#34;&gt;&lt;p&gt;info 提示块标签&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&#34;note warning disabled&#34;&gt;&lt;p&gt;warning 提示块标签&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&#34;note danger disabled&#34;&gt;&lt;p&gt;danger 提示块标签&lt;/p&gt;
&lt;/div&gt;

&lt;ol start=&#34;5&#34;&gt;
&lt;li&gt;&lt;code&gt;no-icon&lt;/code&gt;样式&lt;/li&gt;
&lt;/ol&gt;
&lt;div class=&#34;note no-icon flat&#34;&gt;&lt;p&gt;默认 提示块标签&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&#34;note default no-icon flat&#34;&gt;&lt;p&gt;default 提示块标签&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&#34;note primary no-icon flat&#34;&gt;&lt;p&gt;primary 提示块标签&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&#34;note success no-icon flat&#34;&gt;&lt;p&gt;success 提示块标签&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&#34;note info no-icon flat&#34;&gt;&lt;p&gt;info 提示块标签&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&#34;note warning no-icon flat&#34;&gt;&lt;p&gt;warning 提示块标签&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&#34;note danger no-icon flat&#34;&gt;&lt;p&gt;danger 提示块标签&lt;/p&gt;
&lt;/div&gt;

&lt;p&gt;&lt;code&gt;方法二&lt;/code&gt;&lt;/p&gt;
&lt;p&gt;图标支持 &lt;code&gt;fontawesome&lt;/code&gt; 和 &lt;code&gt;主题内置的阿里图标&lt;/code&gt;，使用方法为加上对应的类名，&lt;code&gt;fontawesome&lt;/code&gt;图标需开启主题配置文件中&lt;code&gt;icons.fontawesome&lt;/code&gt;，默认未开启 fontawesome&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;simple 样式&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;&lt;code&gt;主题内置阿里图标&lt;/code&gt;&lt;/p&gt;
&lt;div class=&#34;note anzhiyufont anzhiyu-icon-rocket simple&#34;&gt;&lt;p&gt;你是刷 Visa 还是 UnionPay&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&#34;note blue anzhiyufont anzhiyu-icon-bullhorn simple&#34;&gt;&lt;p&gt;2022 年快到了….&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&#34;note pink anzhiyufont anzhiyu-icon-instagram simple&#34;&gt;&lt;p&gt;小心开车 安全至上&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&#34;note red anzhiyufont anzhiyu-icon-fan simple&#34;&gt;&lt;p&gt;这是三片呢？还是四片？&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&#34;note orange anzhiyufont anzhiyu-icon-dengpao simple&#34;&gt;&lt;p&gt;你是刷 Visa 还是 UnionPay&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&#34;note purple anzhiyufont anzhiyu-icon-sanmingzhi simple&#34;&gt;&lt;p&gt;剪刀石头布&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&#34;note green anzhiyufont anzhiyu-icon-ic_train simple&#34;&gt;&lt;p&gt;前端最讨厌的浏览器&lt;/p&gt;
&lt;/div&gt;

&lt;p&gt;&lt;code&gt;fontawesome 图标&lt;/code&gt;，开启主题配置文件中的&lt;code&gt;icons.fontawesome&lt;/code&gt;为&lt;code&gt;true&lt;/code&gt;后可见&lt;/p&gt;
&lt;div class=&#34;note icon-padding simple&#34;&gt;&lt;i class=&#34;note-icon fab fa-cc-visa&#34;&gt;&lt;/i&gt;&lt;p&gt;你是刷 Visa 还是 UnionPay&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&#34;note blue icon-padding simple&#34;&gt;&lt;i class=&#34;note-icon fas fa-bullhorn&#34;&gt;&lt;/i&gt;&lt;p&gt;2022 年快到了….&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&#34;note pink icon-padding simple&#34;&gt;&lt;i class=&#34;note-icon fas fa-car-crash&#34;&gt;&lt;/i&gt;&lt;p&gt;小心开车 安全至上&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&#34;note red icon-fan simple&#34;&gt;&lt;p&gt;这是三片呢？还是四片？&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&#34;note orange icon-padding simple&#34;&gt;&lt;i class=&#34;note-icon fas fa-battery-half&#34;&gt;&lt;/i&gt;&lt;p&gt;你是刷 Visa 还是 UnionPay&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&#34;note purple icon-padding simple&#34;&gt;&lt;i class=&#34;note-icon far fa-hand-scissors&#34;&gt;&lt;/i&gt;&lt;p&gt;剪刀石头布&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&#34;note green icon-padding simple&#34;&gt;&lt;i class=&#34;note-icon fab fa-internet-explorer&#34;&gt;&lt;/i&gt;&lt;p&gt;前端最讨厌的浏器&lt;/p&gt;
&lt;/div&gt;

&lt;ol start=&#34;2&#34;&gt;
&lt;li&gt;modern 样式&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;&lt;code&gt;主题内置阿里图标&lt;/code&gt;&lt;/p&gt;
&lt;div class=&#34;note anzhiyufont anzhiyu-icon-rocket modern&#34;&gt;&lt;p&gt;你是刷 Visa 还是 UnionPay&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&#34;note blue anzhiyufont anzhiyu-icon-bullhorn modern&#34;&gt;&lt;p&gt;2022 年快到了….&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&#34;note pink anzhiyufont anzhiyu-icon-instagram modern&#34;&gt;&lt;p&gt;小心开车 安全至上&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&#34;note red anzhiyufont anzhiyu-icon-fan modern&#34;&gt;&lt;p&gt;这是三片呢？还是四片？&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&#34;note orange anzhiyufont anzhiyu-icon-dengpao modern&#34;&gt;&lt;p&gt;你是刷 Visa 还是 UnionPay&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&#34;note purple anzhiyufont anzhiyu-icon-sanmingzhi modern&#34;&gt;&lt;p&gt;剪刀石头布&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&#34;note green anzhiyufont anzhiyu-icon-ic_train modern&#34;&gt;&lt;p&gt;前端最讨厌的浏览器&lt;/p&gt;
&lt;/div&gt;

&lt;p&gt;&lt;code&gt;fontawesome 图标&lt;/code&gt;，开启主题配置文件中的&lt;code&gt;icons.fontawesome&lt;/code&gt;为&lt;code&gt;true&lt;/code&gt;后可见&lt;/p&gt;

&lt;div class=&#34;note icon-padding modern&#34;&gt;&lt;i class=&#34;note-icon fab fa-cc-visa&#34;&gt;&lt;/i&gt;&lt;p&gt;你是刷 Visa 还是 UnionPay&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&#34;note blue icon-padding modern&#34;&gt;&lt;i class=&#34;note-icon fas fa-bullhorn&#34;&gt;&lt;/i&gt;&lt;p&gt;2021 年快到了….&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&#34;note pink icon-padding modern&#34;&gt;&lt;i class=&#34;note-icon fas fa-car-crash&#34;&gt;&lt;/i&gt;&lt;p&gt;小心开车 安全至上&lt;/p&gt;
&lt;/div&gt;
